// Avancement d'une tâche – contrôle de la demande de l'interface :
//   { tache_id }                  une tâche précise (identifiant UUID)
//   { etage, recent: true }       le dernier rapport d'étage des 16 dernières heures (par exemple celui de 5h30)
const e = $input.first().json?.body ?? {};
if (e.recent === true) {
  const etage = Number(e.etage);
  if (!Number.isInteger(etage) || etage < 0 || etage > 20) throw new Error('étage invalide');
  return [{ json: { tache_id: '', etage: String(etage) } }];
}
const id = String(e.tache_id ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) throw new Error('tache_id invalide');
return [{ json: { tache_id: id, etage: '' } }];

// Avancement d'une tâche – réponse à l'interface.
const demande = $('Contrôler la tâche').first().json;
const t = $input.first().json ?? {};
if (!t.id) {
  if (demande.etage) return [{ json: { tache_id: null } }]; // « le dernier rapport de l'étage » : il n'y en a pas
  throw new Error('Tâche introuvable');
}
return [
  {
    json: {
      tache_id: t.id,
      type: t.type,
      statut: t.statut,
      total: t.total,
      fait: t.fait,
      automatique: t.parametres?.automatique === true,
      cree_le: t.cree_le,
      resultat: t.resultat ?? [],
    },
  },
];

// Contrôle de session – le jeton « Bearer » de l'en-tête Authorization (43 caractères URL-safe) est haché (SHA-256) : seul le haché est en base.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Contrôle de session – résultat : un soignant identifié (session ouverte, non expirée, compte actif) ou rien.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
